WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM web_events), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id_2 FROM gaps) SELECT event_type, (UNIX_TIMESTAMP(MAX(prev_event_time)) - UNIX_TIMESTAMP(MIN(prev_event_time))) / 60 AS duration_min, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, SORT_ARRAY(COLLECT_SET(page)) AS page_list, APPROX_PERCENTILE(session_id_2, 0.9) AS session_id_2_p90, MIN(event_time) AS first_event_time, APPROX_PERCENTILE(session_id_2, 0.95) AS session_id_2_p95 FROM islands GROUP BY event_type;
